def merge_quota(a, b):
    if not a and not b:
        return Result(ok=False, value=None, err='E_EMPTY')
    out = dict(a)
    for k, v in b.items():
        if k in out and out[k] != v:
            return Result(ok=False, value=None, err='E_CONFLICT')
        out[k] = v
    return Result(ok=True, value=out, err=None)

