from aerelith.core.result import Result

UNITS = {'d': 1440, 'h': 60, 'm': 1}

def parse_window(spec):
    if not spec:
        return Result(ok=False, value=None, err='E_EMPTY')
    unit = spec[-1]
    head = spec[:-1]
    if unit not in UNITS or not head.isdigit():
        return Result(ok=False, value=None, err='E_RANGE')
    n = int(head)
    if n <= 0:
        return Result(ok=False, value=None, err='E_RANGE')
    return Result(ok=True, value=n * UNITS[unit], err=None)

