const { clampInt } = require('./aerutil');

function pageOf(rows, page, size) {
  if (!Array.isArray(rows)) return null;
  const s = clampInt(size, 1, 100);
  const p = clampInt(page, 1, 1000);
  if (s === null || p === null) return null;
  return rows.slice((p - 1) * s, (p - 1) * s + s);
}

module.exports = { pageOf };

