const { byId } = require('./aerutil');

function dedupeById(rows) {
  if (!Array.isArray(rows)) return null;
  const m = byId(rows);
  const seen = new Set();
  const out = [];
  for (const r of rows) {
    if (seen.has(r.id)) continue;
    seen.add(r.id);
    out.push(m.get(r.id));
  }
  return out;
}

module.exports = { dedupeById };

