import type { Result } from './result';

export function parsePort(raw: string): Result<number> {
  if (!/^[0-9]+$/.test(raw)) return { ok: false, error: 'bad port' };
  const n = Number(raw);
  if (n < 1 || n > 65535) return { ok: false, error: 'bad port' };
  return { ok: true, value: n };
}

