import type { Result } from './result';

export function splitOk<T>(
  rows: readonly Result<T>[],
): Result<{ values: T[]; errors: string[] }> {
  if (rows.length === 0) return { ok: false, error: 'empty' };
  const values: T[] = [];
  const errors: string[] = [];
  for (const row of rows) {
    if (row.ok) values.push(row.value);
    else errors.push(row.error);
  }
  return { ok: true, value: { values, errors } };
}

